function applyRoleCapabilities(me){
  if(!me)return;
  document.body.dataset.authRole=me.role||'viewer';
  const admin=me.role==='admin',viewer=me.role==='viewer';
  if(!admin&&activeModule==='administration')showModule('applications');
  const adminNav=$('#administrationNav');if(adminNav)adminNav.hidden=!admin;
  $$('[data-admin-only]').forEach(element=>element.hidden=!admin);
  const messagesNav=$('#messagesNav');if(messagesNav)messagesNav.hidden=!(me.permissions?.['messages.read']??true);
  const operationalTasksNav=$('#operationalTasksNav');if(operationalTasksNav)operationalTasksNav.hidden=!(me.permissions?.['tasks.read']??admin);
  const navigationTab=$('[data-admin-tab="navigation"]');if(navigationTab)navigationTab.hidden=!admin;
  const metadataAdd=$('#adminMetadataAdd');if(metadataAdd)metadataAdd.hidden=!(me.permissions?.['admin.manage']??admin);
  if(!admin){const navigationPanel=$('#adminNavigationPanel');if(navigationPanel)navigationPanel.replaceChildren()}
  ['#resetBtn','#supplierRegistryRefresh','#supplierEdrSync','#supplierNazkReviewSync','#frameworksRefresh',
   '#refNazkRefresh','#refAmcuRefresh','#refAmcuUploadBtn','#bidsDataRefresh'].forEach(selector=>{
    const element=$(selector);if(!element)return;
    element.dataset.roleDisabled=admin?'0':'1';
    element.disabled=!admin||element.dataset.runtimeDisabled==='1'||(selector==='#bidsDataRefresh'&&(element.dataset.bidsReady!=='1'||element.dataset.bidsRunning==='1'));
    if(!admin)element.title='Дія доступна лише адміністратору';
    else if(element.dataset.runtimeDisabled!=='1')element.title='';
  });
  const requestsRefresh=$('#requestsRefresh');if(requestsRefresh){
    requestsRefresh.disabled=viewer||requestsRefresh.dataset.runtimeDisabled==='1';
    if(viewer)requestsRefresh.title='Дія недоступна для ролі лише перегляду';
    else if(requestsRefresh.dataset.runtimeDisabled!=='1')requestsRefresh.title='';
  }
  document.body.classList.toggle('role-viewer',viewer);
  if(window.pqmApplyNavigationAccess)window.pqmApplyNavigationAccess(me);
  renderManualBidsUpdateState(manualBidsFeatureState);
  updatePowerbiAvailability();
}
