function syncPrimaryFilters(){if($('#applicationCategoryFilter'))$('#applicationCategoryFilter').value=categoryFilter;if($('#applicationOfficerFilter'))$('#applicationOfficerFilter').value=officerFilter}
function saveFilterState(){localStorage.setItem(filterStateKey,JSON.stringify({search:$('#searchInput').value,protocolNumber:$('#protocolNumberFilter').value,dateFrom:$('#dateFromFilter').value,dateTo:$('#dateToFilter').value,protocolDecision:$('#protocolDecisionFilter').value,complianceStatus:$('#complianceStatusFilter').value,officer:officerFilter,category:categoryFilter,sortKey,sortDirection,selections:Object.fromEntries(Object.entries(filterSelections).map(([key,value])=>[key,[...value]]))}));syncPrimaryFilters();syncFilterUrl()}
function restoreFilterState(){try{const state=JSON.parse(localStorage.getItem(filterStateKey)||'null')||{};const query=new URLSearchParams(location.search);$('#searchInput').value=query.get('search')??state.search??'';$('#dateFromFilter').value=query.get('date_from')??state.dateFrom??'';$('#dateToFilter').value=query.get('date_to')??state.dateTo??'';$('#protocolNumberFilter').value=query.get('protocol_number')??state.protocolNumber??'';$('#protocolDecisionFilter').value=state.protocolDecision||'';$('#complianceStatusFilter').value=state.complianceStatus||'';officerFilter=query.get('officer')??state.officer??'';categoryFilter=query.get('category')??state.category??'';sortKey=state.sortKey||'receivedDate';sortDirection=state.sortDirection==='asc'?'asc':'desc';Object.entries(state.selections||{}).forEach(([key,values])=>{if(!filterSelections[key]||!Array.isArray(values))return;filterSelections[key].clear();values.forEach(value=>filterSelections[key].add(value))});$$('.multi-filter input[type="checkbox"]').forEach(input=>{input.checked=Object.values(filterSelections).some(selection=>selection.has(input.value))});syncPrimaryFilters()}catch{localStorage.removeItem(filterStateKey)}}
