function updateApplicationFilterStyles(){
  const toggle=(selector,active)=>$(selector)?.classList.toggle('filter-active',Boolean(active));
  toggle('#searchInput',$('#searchInput').value.trim());
  toggle('#statusFilter',filterSelections.status.size);
  toggle('#marketplaceDecisionFilter',filterSelections.marketplace.size);
  toggle('#applicationCategoryFilter',categoryFilter);
  toggle('#applicationOfficerFilter',officerFilter);
  toggle('#registryStatusFilter',filterSelections.registry.size);
  toggle('#supplierCodeFilter',filterSelections.supplier.size);
  toggle('#frameworkFilter',filterSelections.framework.size);
  toggle('#dkFilter',filterSelections.dk.size);
  toggle('#protocolNumberFilter',$('#protocolNumberFilter').value.trim());
  toggle('#protocolDecisionFilter',$('#protocolDecisionFilter').value);
  const decisionValue=$('#protocolDecisionFilter').value;
  const decisionKeys={admit:'decision_yes',reject:'decision_no',__empty__:'decision_undefined'};
  $$('.decision-kpi').forEach(card=>card.classList.toggle('active',decisionKeys[decisionValue]===card.dataset.kpiCard));
  toggle('#complianceStatusFilter',$('#complianceStatusFilter').value);
  toggle('#dateFromFilter',$('#dateFromFilter').value);
  toggle('#dateToFilter',$('#dateToFilter').value);
  const advanced=[$('#protocolNumberFilter').value.trim(),filterSelections.registry.size,filterSelections.supplier.size,filterSelections.framework.size,filterSelections.dk.size,$('#protocolDecisionFilter').value,$('#complianceStatusFilter').value,$('#dateFromFilter').value,$('#dateToFilter').value];
  const count=advanced.filter(Boolean).length,details=$('.advanced-filters'),summary=details?.querySelector(':scope>summary');
  details?.classList.toggle('filter-active',count>0);if(summary)summary.textContent=count?`Фільтри · ${count}`:'Фільтри';
}
async function loadStats(){const q=new URLSearchParams(currentFilterParams()),signature=q.toString();if(signature===statsSignature)return;statsSignature=signature;try{const data=await request(`${API}/stats?${q}`);$$('[data-kpi]').forEach(el=>el.textContent=Number(data[el.dataset.kpi]||0).toLocaleString('uk-UA'));$('#officerCards').innerHTML=(data.officers||[]).map(item=>`<button type="button" class="officer-card ${item.officer==='Не визначено'?'unassigned':''} ${item.officer===officerFilter?'active':''}" data-officer="${esc(item.officer)}"><span title="${esc(formatOfficerName(item.officer))}">${esc(formatOfficerName(item.officer))}</span><strong>${Number(item.applications||0).toLocaleString('uk-UA')}</strong></button>`).join('');$$('#officerCards [data-officer]').forEach(card=>card.onclick=()=>{officerFilter=officerFilter===card.dataset.officer?'':card.dataset.officer;page=1;statsSignature='';loadRows()})}catch(e){statsSignature='';toast(e.message)}}
async function loadRows(){
  const generation=++loadRowsGeneration;
  let refreshStats=false;
  updateApplicationFilterStyles();saveFilterState();loading=true;render();
  try{
    const q=new URLSearchParams({...currentFilterParams(),page,size:'50',sort:sortKey,direction:sortDirection,sorts:JSON.stringify(multiSort)});
    const data=await request(`${API}/applications?${q}`);
    if(generation!==loadRowsGeneration)return;
    rows=data.items.map(mapRow);page=data.page;pages=data.pages||1;total=data.total;selected.clear();
    refreshStats=true;
  }catch(e){
    if(generation===loadRowsGeneration){rows=[];total=0;pages=1;selected.clear();toast(`Не вдалося застосувати фільтр: ${e.message}`)}
  }finally{
    if(generation===loadRowsGeneration){loading=false;render();if(refreshStats)void loadStats()}
  }
}
