  const move=(from,to)=>{const ordered=[...p.columns].sort((a,b)=>a.order-b.order);if(from<0||to<0||to>=ordered.length)return;const [moved]=ordered.splice(from,1);ordered.splice(to,0,moved);ordered.forEach((c,i)=>c.order=i);persistProfileColumns();draw();render()};
  search.oninput=draw;draw();
