  const schedule=unavailable?'Автооновлення вимкнено':stopped?'Планувальник не працює':state.scheduler_running&&state.next_run_at?`Наступне автооновлення: ${displayDate(state.next_run_at)}`:'Стан автооновлення невідомий';
