let violationReports=[],requestsTimer,requestsPolling,selectedRequestAuthority='',requestsPage=1,requestsPages=1;
const requestStatusLabels={draft:'Чернетка',pending:'Очікує розгляду',answered:'Надано відповідь',satisfied:'Задоволено',declined:'Відхилено',cancelled:'Скасовано'};
const requestReasonLabels={contractBreach:'пп. 1 п. 49 — Непідписання договору/ненадання забезпечення в строк',signingRefusal:'пп. 2 п. 49 — Письмова відмова від укладення договору',goodsNonCompliance:'пп. 3 п. 49 — Невиконання зобов’язань за договором',supplierMisconduct:'Недобросовісна поведінка постачальника'};
const queueReasonLabels={contractBreach:'пп. 1 п. 49',signingRefusal:'пп. 2 п. 49',goodsNonCompliance:'пп. 3 п. 49'};
const violationReviewStatusLabels={not_reviewed:'Не розглянуто',in_review:'На розгляді',reviewed:'Розглянуто',completed:'Завершено'};
function queueReasonLabel(value){let result=String(value||'');for(const [technical,label] of Object.entries(queueReasonLabels))result=result.replace(new RegExp(`(^| · )${technical}(?=$| · )`,'g'),(_,prefix)=>`${prefix}${label}`);return result.split(' · ').join('\n')}
function requestLabel(value,map){return map[value]||value||'—'}
function requestDocumentLinks(documents){return (documents||[]).map(doc=>`<a href="${esc(doc.url)}" target="_blank" rel="noopener">${esc(doc.title||'Документ')}</a>`).join('<br>')||'—'}
function requestViolationUrl(item){return item.contract_pretty_id?`https://prozorro.gov.ua/uk/contract/${encodeURIComponent(item.contract_pretty_id)}/violation-reports${item.report_id?`#report-${encodeURIComponent(item.report_id)}`:''}`:''}
function requestBlockingBadge(item){const m=item.blocking_marker;if(!m?.used_for_blocking)return '';return `<small class="blocking-used-badge ${m.highlighting_active?'active':'historical'}" title="${esc(displayDateOnly(m.blocking_start_date))}–${esc(displayDateOnly(m.blocking_end_date))}">${m.highlighting_active?'Використано для блокування':'Було використано для блокування'}</small>`}
function requestTenderLinks(item){const links=[];if(item.tender_pretty_id)links.push(`<a href="https://prozorro.gov.ua/uk/tender/${encodeURIComponent(item.tender_pretty_id)}" target="_blank" rel="noopener">${esc(item.tender_pretty_id)}</a>`);if(item.contract_pretty_id)links.push(`<a href="https://prozorro.gov.ua/uk/contract/${encodeURIComponent(item.contract_pretty_id)}" target="_blank" rel="noopener">${esc(item.contract_pretty_id)}</a>`);const url=requestViolationUrl(item);if(url)links.push(`<a href="${url}" target="_blank" rel="noopener">${esc(item.report_id||'Звернення в Prozorro')}</a>`);return links.join('<br>')||'—'}
function requestAuthorityShortName(item){const name=item.authority_name||item.authority_code||'Адміністратор';if(item.authority_code==='40996564')return'Професійні закупівлі';if(/медичні закупівлі/i.test(name))return'МЗУ';if(/державний оператор тилу/i.test(name))return'ДОТ';if(/агенц.*оборонн.*закуп/i.test(name))return'АОЗ';if(/українські спеціальні системи/i.test(name))return'УСС';return name}
function renderRequestAuthorityCards(items){const box=$('#requestAuthorityCards');box.innerHTML=(items||[]).map(item=>`<button type="button" class="request-authority-card${selectedRequestAuthority===item.authority_code?' active':''}" data-authority-code="${esc(item.authority_code)}" title="${esc(item.authority_name)} · ${esc(item.authority_code)}"><span>${esc(requestAuthorityShortName(item))}</span><strong>${Number(item.count||0).toLocaleString('uk-UA')}</strong></button>`).join('');box.hidden=!box.children.length}
function requestDeadline(item){if(!item.defendant_period_end)return{html:'—',ready:true};const end=new Date(item.defendant_period_end),now=new Date(),ready=now>=end;if(ready)return{html:`<strong>${esc(displayDate(item.defendant_period_end))}</strong><small class="deadline-ready">Строк сплив — можна розглядати</small>`,ready:true};const ms=end-now,days=Math.floor(ms/86400000),hours=Math.floor((ms%86400000)/3600000);return{html:`<strong>${esc(displayDate(item.defendant_period_end))}</strong><small class="deadline-wait">Ще ${days?days+' дн. ':''}${hours} год. — розгляд недоступний</small>`,ready:false}}
function requestStatements(item){const statements=item.defendant_statements||[];if(!statements.length)return'<p class="muted">Пояснення постачальника не надано.</p>';return statements.map((statement,index)=>`<div class="request-statement"><p><strong>Пояснення ${statements.length>1?index+1:''}</strong>${statement.datePublished?` · ${esc(displayDate(statement.datePublished))}`:''}</p><div class="request-long-text">${esc(statement.description||'Текст відсутній').replaceAll('\n','<br>')}</div><div class="request-documents">${requestDocumentLinks(statement.documents)}</div></div>`).join('')}
function populateRequestSelect(id,values,labels,empty){const select=$(id),current=select.value;select.innerHTML=`<option value="">${empty}</option>`+(values||[]).map(value=>`<option value="${esc(value)}">${esc(requestLabel(value,labels))}</option>`).join('');select.value=current}
async function loadViolationReports(){const body=$('#requestsBody');body.innerHTML='<tr><td colspan="10">Завантаження…</td></tr>';try{const q=new URLSearchParams({search:$('#requestsSearch').value.trim(),status:$('#requestsStatus').value,reason:$('#requestsReason').value,authority_code:selectedRequestAuthority,date_from:$('#requestsDateFrom').value,date_to:$('#requestsDateTo').value,page:String(requestsPage),size:'100'});const data=await request(`${API}/violation-reports?${q}`);requestsPages=Math.max(1,Number(data.pages||1));if(requestsPage>requestsPages){requestsPage=requestsPages;return loadViolationReports()}violationReports=data.items||[];$('#requestsPending').textContent=Number(data.pending||0).toLocaleString('uk-UA');$('#requestsSatisfied').textContent=Number(data.satisfied||0).toLocaleString('uk-UA');$('#requestsDeclined').textContent=Number(data.declined||0).toLocaleString('uk-UA');$$('#requestQuickFilters [data-status]').forEach(button=>button.classList.toggle('active',button.dataset.status===$('#requestsStatus').value));populateRequestSelect('#requestsStatus',data.statuses,requestStatusLabels,'Усі статуси');populateRequestSelect('#requestsReason',data.reasons,requestReasonLabels,'Усі підстави');renderRequestAuthorityCards(data.authorities);const sync=data.sync||{};$('#requestsRefresh').disabled=Boolean(sync.running);$('#requestsSyncStatus').textContent=sync.running?(sync.message||'Синхронізація триває…'):(sync.updated_at?`${sync.message} · ${displayDate(sync.updated_at)}`:'Натисніть «Оновити з Prozorro», щоб завантажити офіційний реєстр');body.innerHTML=violationReports.length?violationReports.map((item,index)=>{const deadline=requestDeadline(item),statements=item.defendant_statements||[];return`<tr class="request-row ${item.blocking_marker?.highlighting_active?'request-blocking-active':''}" data-request-index="${index}"><td><strong>${esc(item.report_id||item.id)}</strong>${requestBlockingBadge(item)}</td><td>${esc(displayDate(item.date_published))}</td><td><strong>${esc(item.author_name)||'—'}</strong><small>${esc(item.author_code)}</small></td><td><strong>${esc(item.defendant_name)||'—'}</strong><small>${esc(item.defendant_code)}</small></td><td>${esc(requestLabel(item.reason,requestReasonLabels))}</td><td>${deadline.html}${statements.length?`<small class="statement-received">Пояснення надано: ${statements.length}</small>`:''}</td><td>${requestTenderLinks(item)}</td><td><span class="request-status status-${esc(item.status)}">${esc(requestLabel(item.status,requestStatusLabels))}</span></td><td>${esc(requestLabel(item.decision_resolution,requestStatusLabels))}</td><td>${Number((item.evidence_documents||[]).length)+Number((item.decision_documents||[]).length)+statements.reduce((n,s)=>n+(s.documents||[]).length,0)}</td></tr>`}).join(''):'<tr><td colspan="10">Звернень за вибраними умовами не знайдено</td></tr>';const total=Number(data.total||0),from=total?(requestsPage-1)*100+1:0,to=Math.min(requestsPage*100,total);$('#requestsPageInfo').textContent=`Показано ${from}–${to} із ${total.toLocaleString('uk-UA')} звернень · сторінка ${requestsPage} із ${requestsPages}`;$('#requestsPrev').disabled=requestsPage<=1;$('#requestsNext').disabled=requestsPage>=requestsPages;if(sync.running&&!requestsPolling)requestsPolling=setInterval(async()=>{try{const fresh=await loadViolationReports();if(!fresh?.sync?.running){clearInterval(requestsPolling);requestsPolling=null}}catch{}},2500);return data}catch(error){body.innerHTML=`<tr><td colspan="10">${esc(error.message)}</td></tr>`;throw error}}
const internalDecisionLabels={warning:'Попередження',decline:'Відмова в задоволенні звернення',individual_review:'Індивідуальний розгляд'};
function requestContextBlock(item){const c=item.procurement_context||{},r=item.review||{};if(!c.available)return`<section><h3>Перевірка УО</h3><p class="request-warning">Контекст закупівлі не отримано: ${esc(c.error||'невідома помилка')}</p></section>`;const common=`<div class="request-context-grid"><div><small>Дата визначення переможцем</small><strong>${esc(displayDate(c.winner_selected_at))||'—'}</strong></div><div><small>Award переможця</small><strong>${esc(c.winner_award_id)||'—'}</strong></div></div>`;let reason='';if(item.reason==='contractBreach'){reason=`<div class="request-context-grid"><div><small>5-й календарний день</small><strong>${esc(displayDateOnly(c.day_5))||'—'}</strong></div><div><small>Перенесення вихідного</small><strong>${c.day_5_shifted?'Так':'Ні'}</strong></div><div><small>Граничний строк</small><strong>${esc(displayDateOnly(c.contract_deadline))||'—'}</strong></div><div><small>Забезпечення договору</small><strong>${c.contract_guarantee_required?'Так':'Ні'}${c.contract_guarantee_value!=null?` · ${esc(c.contract_guarantee_value)} ${esc(c.contract_guarantee_unit||'')}`:''}</strong></div></div><label class="request-check"><input type="checkbox" data-review="contract_deadline_extended" ${r.contract_deadline_extended?'checked':''}> Строк укладення договору продовжено до 10 к.д.</label>${c.rejection_present?`<div class="request-result"><strong>Відхилення: ${esc(displayDate(c.rejection_date))||'—'}</strong><p>${esc(c.rejection_title||c.rejection_description||'Підстава не зазначена')}</p>${requestDocumentLinks(c.rejection_documents)}</div>`:`<div class="request-result neutral"><strong>Пропозицію переможця не відхилено.</strong><p>Перевірка дострокового відхилення не застосовується.</p></div>`}`}
if(item.reason==='signingRefusal'){reason=`<div class="request-context-grid"><div><small>3-й календарний день</small><strong>${esc(displayDateOnly(c.day_3))||'—'}</strong></div><div><small>Перенесення вихідного</small><strong>${c.day_3_shifted?'Так':'Ні'}</strong></div><div><small>Гранична дата</small><strong>${esc(displayDateOnly(c.written_refusal_deadline))||'—'}</strong></div></div><div class="request-form-grid"><label>Дата письмової відмови<input type="date" data-review="written_refusal_date" value="${esc(r.written_refusal_date||'')}"></label><label>Вих. №<input data-review="written_refusal_number" value="${esc(r.written_refusal_number||'')}"></label><label>Посилання<input type="url" data-review="written_refusal_url" value="${esc(r.written_refusal_url||'')}"></label></div>`}
if(item.reason==='goodsNonCompliance'){reason=`<fieldset class="request-radio"><legend>Є рішення суду, що набрало законної сили?</legend><label><input type="radio" name="courtFinal" data-review="court_decision_final_present" value="true" ${r.court_decision_final_present===true?'checked':''}> Так</label><label><input type="radio" name="courtFinal" data-review="court_decision_final_present" value="false" ${r.court_decision_final_present===false?'checked':''}> Ні</label></fieldset>`}
const recommendation=item.recommendation||{};return`<section class="request-review"><h3>Перевірка УО</h3>${common}${reason}<div class="request-recommendation"><small>Рекомендація системи</small><strong>${esc(internalDecisionLabels[recommendation.recommended_decision]||'Потрібна оцінка УО')}</strong><p>${esc(recommendation.recommendation_reason||'')}</p></div><div class="request-form-grid"><label>Статус розгляду<select data-review="review_status"><option value="not_reviewed">Не розглянуто</option><option value="in_review">На розгляді</option><option value="completed">Завершено</option></select></label><label>Відповідальна особа<input data-review="assigned_officer" value="${esc(r.assigned_officer||'')}"></label><label>Рішення УО<select data-review="internal_decision"><option value="">Не визначено</option>${Object.entries(internalDecisionLabels).map(([value,label])=>`<option value="${value}" ${r.internal_decision===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="wide">Нотатки<textarea data-review="review_notes">${esc(r.review_notes||'')}</textarea></label><label>Перевірена повна назва замовника<input data-review="customer_verified_full_name" value="${esc(r.customer_verified_full_name||'')}"></label><label>Скорочена назва замовника<input data-review="customer_verified_short_name" value="${esc(r.customer_verified_short_name||'')}"></label><label>Фактична дата договору<input type="date" data-review="actual_contract_date" value="${esc(r.actual_contract_date||'')}"></label><label>№ договору<input data-review="actual_contract_number" value="${esc(r.actual_contract_number||'')}"></label><label>Посилання на договір<input type="url" data-review="actual_contract_url" value="${esc(r.actual_contract_url||'')}"></label></div><button type="button" id="saveViolationReview" class="primary">Зберегти</button></section>`}
function violationDetailHtml(item){const deadline=requestDeadline(item),clarity=item.author_code?` <a href="https://clarity-project.info/edr/${encodeURIComponent(item.author_code)}" target="_blank" rel="noopener">Перевірити в Clarity</a>`:'';return`${item.is_read_only?'<div class="request-readonly">Є офіційне рішення Prozorro — картка доступна лише для перегляду.</div>':''}<section><h3>Замовник</h3><p>${esc(item.author_name)||'—'}${item.author_code?` · ${esc(item.author_code)}`:''}${clarity}</p></section><section><h3>Постачальник</h3><p>${esc(item.defendant_name)||'—'}${item.defendant_code?` · ${esc(item.defendant_code)}`:''}</p>${item.supplier_verified?`<small>Перевірена назва: ${esc(item.supplier_verified.full_name||item.supplier_verified.short_name||'—')}</small>`:''}</section><section><h3>Закупівля, договір і звернення</h3><p>${requestTenderLinks(item)}</p></section><section><h3>Строк надання пояснень</h3><p>${deadline.html}</p></section><section><h3>Підстава звернення</h3><p><strong>${esc(requestLabel(item.reason,requestReasonLabels))}</strong></p><div class="request-long-text">${esc(item.description||'Опис відсутній').replaceAll('\n','<br>')}</div></section><section><h3>Пояснення постачальника</h3>${requestStatements(item)}</section><section><h3>Рішення адміністратора</h3><p><strong>${esc(requestLabel(item.decision_resolution,requestStatusLabels))}</strong>${item.decision_date?` · ${esc(displayDate(item.decision_date))}`:''}</p><div class="request-long-text">${esc(item.decision_description||'Рішення відсутнє').replaceAll('\n','<br>')}</div></section><section class="request-documents"><h3>Документи звернення</h3>${requestDocumentLinks(item.evidence_documents)}</section><section class="request-documents"><h3>Документи рішення</h3>${requestDocumentLinks(item.decision_documents)}</section>${item.is_read_only?'':requestContextBlock(item)}`}
function collectViolationReview(){const payload={};$$('#requestDetailsBody [data-review]').forEach(input=>{const key=input.dataset.review;if(input.type==='radio'){if(input.checked)payload[key]=input.value==='true'}else if(input.type==='checkbox')payload[key]=input.checked;else payload[key]=input.value});return payload}
async function saveViolationReview(reportId){try{const data=await request(`${API}/violation-reports/${encodeURIComponent(reportId)}/review`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(collectViolationReview())});$('#requestDetailsBody').innerHTML=violationDetailHtml(data);bindViolationReview(data);toast('Розгляд збережено')}catch(error){toast(error.message);try{const fresh=await request(`${API}/violation-reports/${encodeURIComponent(reportId)}`);$('#requestDetailsBody').innerHTML=violationDetailHtml(fresh);bindViolationReview(fresh)}catch{}}}
