const frameworkNumber=value=>Number(value||0).toLocaleString('uk-UA');
function frameworkStatus(raw){
  const value=String(raw||'').trim(),key=value.toLowerCase();
  if(['active','активне','активний','активна'].includes(key))return{key:'active',label:'Активний'};
  if(['cancelled','canceled','скасоване','скасований','скасовано'].includes(key))return{key:'closed',label:'Скасований'};
  if(['closed','complete','inactive','disabled','unsuccessful','закрите','закритий','закрито','неактивне','неактивний'].includes(key))return{key:'closed',label:'Закритий'};
  return{key:'other',label:value||'Не визначено'};
}
