let bidsUpdateTimer=null;
function renderBidsRun(state){
 const button=$('#bidsDataRefresh');button.dataset.bidsReady='1';button.dataset.bidsRunning=state.running?'1':'0';
 button.disabled=Boolean(state.running)||currentMe?.role!=='admin'||button.dataset.runtimeDisabled==='1';
 let details=$('#bidsLiveRun');if(!details){details=document.createElement('div');details.id='bidsLiveRun';$('#bidsSyncHeadline').after(details)}
 const status=state.status||(state.running?'running':state.error?'failed':state.updated_at?'completed':'idle');
 const labels={idle:'Не запущено',running:'Виконується',completed:'Завершено',failed:'Помилка'};
 const seconds=state.duration_seconds??(state.started_at?Math.max(0,Math.floor(((state.finished_at?Date.parse(state.finished_at):Date.now())-Date.parse(state.started_at))/1000)):null);
 const date=x=>x?displayDate(x):'—';
 details.innerHTML=`<p><b>${esc(labels[status]||status)}</b> · Run: ${esc(state.run_id||'ID недоступний у поточному runtime')} · PID: ${esc(state.pid??'—')}</p><p>Старт: ${esc(date(state.started_at))} · Тривалість: ${seconds===null?'—':Math.floor(seconds/60)+' хв '+seconds%60+' с'} · Завершення: ${esc(date(state.finished_at))}</p><p>Етап: ${esc(state.stage||state.message||'—')} · Прогрес: ${state.processed==null||state.total==null?'точні дані недоступні':esc(state.processed)+' / '+esc(state.total)}</p><p>Остання активність: ${esc(date(state.last_activity_at))} · Помилки поточного run: ${esc(state.current_run_errors??'невідомо')}</p><p>Остання помилка: ${esc(state.last_error||state.error||'—')}</p>`;
}
