function operationalCurrentReason(item){if(item.resolution_code==='nazk_record_no_longer_present')return 'Скасовано — запис особи більше відсутній у Реєстрі НАЗК';if(item.resolution_code==='no_active_qualifications')return 'Скасовано — відсутні активні кваліфікації';if(['manager_changed','nazk_not_relevant'].includes(item.resolution_code))return 'Скасовано — змінився керівник';if(item.task_type==='nazk_check'){const state=item.nazk_current_state||{};return operationalNazkStateLabels[state.result]||operationalNazkStateLabels[state.workflow_status]||'Стан НАЗК не визначено'}return operationalTaskReasonLabels[item.source_context?.trigger_reason]||'Операційна дія щодо постачальника'}
// List projection: business trigger, required action and status are separate concepts.
function operationalListTrigger(item){if(item.task_type==='nazk_check')return 'Виявлено запис у Реєстрі НАЗК';return operationalTaskReasonLabels[item.source_context?.trigger_reason]||'Операційна дія щодо постачальника'}
function operationalListAction(item){
  if(['completed','cancelled'].includes(item.status))return '';
  if(item.task_type==='nazk_check'){
    if(['waiting_external','awaiting_response'].includes(item.status))return 'Очікувати / опрацювати відповідь';
    if(['ready_for_document','ready_for_exclusion'].includes(item.status))return 'Підготувати рішення про виключення';
    if(['new','in_progress'].includes(item.status)&&!['confirmed','refuted'].includes(item.nazk_current_state?.result))return 'Перевірити збіг';
    return '';
  }
  return item.needs_action?'Потребує опрацювання':'Очікує наступного етапу';
}
let operationalTaskTimer=null;
