function operationalHistoryHtml(events=[]){const labels={supplier_request_generated:'Сформовано запит постачальнику',threshold_reconciled_to_rolling:'Уточнено період підрахунку попереджень',protocol_decision_attached:'Прив’язано протокольне рішення',legacy_blocking_confirmed:'Виконання блокування підтверджено',created:'Задачу створено',assigned:'Призначено відповідальну УО',status_changed:'Статус змінено',request_sent:'Запит направлено',response_received:'Отримано відповідь / інформацію',post_close_information:'Додано інформацію після закриття',amcu_extract_url_added:'Оновлено посилання на витяг АМКУ',nazk_refuted:'НАЗК · Спростовано',nazk_result_refuted:'НАЗК · Спростовано',nazk_confirmed:'НАЗК · Підтверджено',nazk_result_confirmed:'НАЗК · Підтверджено',nazk_insufficient:'НАЗК · Недостатньо інформації',nazk_result_insufficient:'НАЗК · Недостатньо інформації',cancelled_no_active_qualifications:'Скасовано: відсутні активні кваліфікації',cancelled_manager_changed:'Скасовано: змінився керівник'};return `<section><h3>Історія задачі</h3><div class="operational-history">${events.map(x=>`<div><strong>${esc(labels[x.event_type]||x.event_type)}</strong><span>${esc(displayDate(x.created_at))} · ${esc(x.actor||'Система')}</span></div>`).join('')||'<p>Подій ще немає</p>'}</div></section>`}
function operationalQualificationsHtml(items=[]){return `<section><h3>Активні кваліфікації · ${items.length}</h3>${items.map(x=>`<p><strong>${esc(x.framework_pretty_id||x.framework_id)}</strong> · ${esc(x.dk_code||'')} · ${esc(x.framework_title||'')}</p>`).join('')||'<p>Активних кваліфікацій немає</p>'}</section>`}
function operationalNazkHtml(item){const n=item.nazk_current_state||{},manager=item.current_manager||{},channels=item.channels||{},records=item.nazk_records||[],terminal=['completed','cancelled'].includes(item.status),channel=x=>channels[x]||{status:'not_sent'},channelLabel={not_sent:'Не направлено',document_prepared:'Документ підготовлено',waiting:'Очікується відповідь',response_received:'Відповідь отримано',closed:'Закрито',cancelled:'Скасовано'};return `<section><h3>Поточний стан НАЗК</h3><dl class="operational-facts"><div><dt>Фактичний результат</dt><dd>${esc(operationalNazkStateLabels[n.result]||operationalNazkStateLabels[n.workflow_status]||'Не визначено')}</dd></div><div><dt>Особа задачі</dt><dd>${esc(n.manager_name||item.source_context?.person_name||'—')} · <b>${item.task_person_is_current?'Поточний керівник':'Попередній керівник'}</b></dd></div><div><dt>Поточний керівник</dt><dd>${esc(manager.manager_name||'Не визначено')}</dd></div><div><dt>РНОКПП</dt><dd>${esc(manager.manager_tax_id||'Не зазначено')}</dd></div></dl></section><section><h3>Дані Реєстру НАЗК</h3>${records.map(x=>`<article class="operational-record"><strong>${esc(x.full_name||'—')}</strong><p>${esc(x.offense_name||x.punishment||'Відомості не зазначені')}</p><small>${esc(x.source_id)} · ${esc(displayDateOnly(x.sentence_date))}${x.court_case_number?` · справа ${esc(x.court_case_number)}`:''}</small>${x.decision_url?`<a href="${esc(x.decision_url)}" target="_blank" rel="noopener">Відкрити джерело</a>`:''}</article>`).join('')||'<p>Пов’язаних записів не знайдено</p>'}</section><section><h3>Зовнішні запити</h3><div class="operational-channels">${[['supplier','Постачальнику'],['nazk','До НАЗК']].map(([key,label])=>`<div><strong>${label}</strong><span>${esc(channelLabel[channel(key).status]||channel(key).status)}</span>${!terminal?`<button type="button" class="ghost operational-request-sent" data-channel="${key}">Зафіксувати направлення</button>`:''}<button type="button" class="ghost operational-document-hook" disabled title="Буде доступно після підключення Конструктора шаблонів">Сформувати запит</button></div>`).join('')}</div></section><section><h3>${terminal?'Інформація після закриття':'Отримані відповіді'}</h3>${(item.responses||[]).map(x=>`<p><strong>${x.source==='nazk'?'НАЗК':'Постачальник'}</strong> · ${esc(displayDateOnly(x.response_date))||'дата не зазначена'} · ${esc(x.summary||'Без короткого змісту')}</p>`).join('')||'<p>Відповідей ще немає</p>'}<button type="button" class="primary operational-add-response">${terminal?'Додати інформацію після закриття':'Додати відповідь / інформацію'}</button></section>`}
function operationalAmcuHtml(item){return `<section><h3>Рішення АМКУ</h3><div class="operational-table"><table><thead><tr><th>№ рішення</th><th>Дата</th><th>Орган АМКУ</th><th>Посилання на витяг</th></tr></thead><tbody>${(item.amcu_decisions||[]).map(x=>`<tr><td>${esc(x.decision_no||'—')}</td><td>${esc(displayDateOnly(x.decision_date))||'—'}</td><td>${esc(x.authority||'—')}</td><td><input data-amcu-decision="${esc(x.row_key)}" value="${esc(x.extract_url||'')}" placeholder="https://…"><button type="button" class="ghost operational-amcu-save" data-decision="${esc(x.row_key)}">Зберегти</button></td></tr>`).join('')||'<tr><td colspan="4">Рішень не знайдено</td></tr>'}</tbody></table></div>${(item.amcu_decisions||[]).some(x=>!x.extract_url)?'<p class="request-warning">Додайте посилання на витяг для всіх рішень АМКУ.</p>':'<p class="operational-ready">Всі рішення мають посилання; задачу можна готувати до документа.</p>'}<button type="button" class="ghost operational-document-hook" disabled title="Буде доступно після підключення Конструктора шаблонів">Сформувати протокол про виключення</button></section>${operationalQualificationsHtml(item.effective_applications||[])}`}
function operationalWarningHtml(item){const s=item.source_context||{};return `<section><h3>Підстава блокування</h3><dl class="operational-facts"><div><dt>Поріг</dt><dd>${s.threshold_type==='3_in_1_rolling_month'?'3 попередження за 1 календарний місяць':'5 попереджень за 3 календарні місяці'}</dd></div><div><dt>Останнє попередження</dt><dd>${esc(displayDateOnly(s.threshold_reached_at))}</dd></div><div><dt>Початок блокування</dt><dd>${esc(displayDateOnly(s.blocking_start_date))}</dd></div><div><dt>Завершення 90 к.д.</dt><dd>${esc(displayDateOnly(s.blocking_end_date))}</dd></div></dl></section><section><h3>Попередження, використані для блокування</h3><div class="operational-table"><table><thead><tr><th>UA-D</th><th>Дата</th><th>Закупівля</th><th>Замовник</th><th>Посилання</th></tr></thead><tbody>${(item.warnings||[]).map(x=>`<tr><td>${esc(x.report_id||'—')}</td><td>${esc(displayDateOnly(x.warning_date))}</td><td>${esc(x.tender_pretty_id||'—')}</td><td>${esc(x.author_name||'—')}</td><td>${requestViolationUrl(x)?`<a href="${esc(requestViolationUrl(x))}" target="_blank" rel="noopener">Відкрити</a>`:'—'}</td></tr>`).join('')}</tbody></table></div><button type="button" class="ghost operational-document-hook" disabled title="Буде доступно після підключення Конструктора шаблонів">Сформувати протокол про блокування</button></section>`}
