const schedulerJobLabels={prozorro:'Заявки / Prozorro',violation_reports:'Звернення замовників',nazk_registry:'Реєстр НАЗК'};
const schedulerEnableConfirmations={
  prozorro:'Увімкнути автоматичне оновлення заявок щогодини о :05?',
  violation_reports:'Увімкнути автоматичне оновлення звернень замовників щогодини о :05?',
  nazk_registry:'Увімкнути автоматичне оновлення Реєстру НАЗК у робочі дні о 09:20?'
};
let manualBidsFeatureState={enabled:false,configuration_source:'environment',mode_supported:true};
let googleRuntimeFeatureState={enabled:false,configuration_source:'environment',client_configured:false,oauth_connected:false};
function renderGoogleRuntimeState(feature={}){
  googleRuntimeFeatureState={...googleRuntimeFeatureState,...feature};
  const enabled=googleRuntimeFeatureState.enabled===true,connected=googleRuntimeFeatureState.oauth_connected===true,canManage=role()==='admin';
  const state=$('#googleRuntimeState'),toggle=$('#googleRuntimeToggle'),disconnect=$('#googleDisconnect');
  if(state){state.textContent=`Google integration: ${enabled?'Увімкнено':'Вимкнено'}`;state.className=`runtime-feature-state ${enabled?'enabled':'disabled'}`}
  if(toggle){toggle.hidden=!canManage;toggle.disabled=!canManage;toggle.dataset.enabled=enabled?'false':'true';toggle.textContent=enabled?'Вимкнути':'Увімкнути'}
  if(disconnect){disconnect.hidden=!canManage||!connected;disconnect.disabled=!canManage||!connected}
  if($('#googleClientState'))$('#googleClientState').textContent=googleRuntimeFeatureState.client_configured?'Налаштовано':'Не налаштовано';
  if($('#googleTokenState'))$('#googleTokenState').textContent=connected?'Підключено':'Не підключено';
  if($('#googleLastEdrSync'))$('#googleLastEdrSync').textContent=googleRuntimeFeatureState.last_edr_sync_at?displayDate(googleRuntimeFeatureState.last_edr_sync_at):'—';
  if($('#googleConfigurationSource'))$('#googleConfigurationSource').textContent=googleRuntimeFeatureState.configuration_source==='runtime'?'Адміністратор':'Середовище';
  if($('#googleRuntimeMessage'))$('#googleRuntimeMessage').textContent=googleRuntimeFeatureState.message||'Фактичний стан Google integration';
}
async function toggleGoogleRuntime(){
  const button=$('#googleRuntimeToggle'),enabled=button.dataset.enabled==='true';
  if(enabled&&!confirm('Увімкнути Google integration? OAuth і синхронізація не будуть запущені автоматично.'))return;
  button.disabled=true;
  try{const result=await request(`${API}/admin/runtime-features/google`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});renderGoogleRuntimeState(result.feature);toast(`Google integration ${enabled?'увімкнено':'вимкнено'}`,'success');await Promise.all([loadRuntimeFeatures(),loadSupplierEdrStatus(),loadSupplierNazkReviewStatus()])}catch(error){button.disabled=false;toast(error.message,'error')}
}
async function disconnectGoogle(){
  if(!confirm('Видалити локальне підключення Google? OAuth client configuration залишиться без змін.'))return;
  const button=$('#googleDisconnect');button.disabled=true;
  try{const result=await request(`${API}/admin/google/disconnect`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});renderGoogleRuntimeState(result.feature);toast('Локальне підключення Google видалено','success');await Promise.all([loadRuntimeFeatures(),loadSupplierEdrStatus(),loadSupplierNazkReviewStatus()])}catch(error){button.disabled=false;toast(error.message,'error')}
}
function renderManualBidsUpdateState(feature={}){
  manualBidsFeatureState={...manualBidsFeatureState,...feature};
  const enabled=manualBidsFeatureState.enabled===true,state=$('#bidsManualUpdateState'),toggle=$('#bidsManualUpdateToggle'),update=$('#bidsDataRefresh'),canManage=role()==='admin';
  if(state){state.textContent=`Ручне оновлення Bids: ${enabled?'Увімкнено':'Вимкнено'}`;state.className=`runtime-feature-state ${enabled?'enabled':'disabled'}`;state.title=manualBidsFeatureState.configuration_source==='runtime'?'Налаштовано адміністратором':'Початкове значення середовища'}
  if(toggle){toggle.hidden=!canManage;toggle.disabled=!canManage||manualBidsFeatureState.mode_supported===false;toggle.dataset.enabled=enabled?'false':'true';toggle.textContent=enabled?'Вимкнути':'Увімкнути';toggle.title=manualBidsFeatureState.mode_supported===false?'Поточний режим Bids не підтримує ручне оновлення':''}
  if(update){update.dataset.runtimeDisabled=enabled?'0':'1';update.disabled=!enabled||update.dataset.bidsReady!=='1'||update.dataset.bidsRunning==='1'||!canManage;update.title=enabled?'':'Оновлення ProzorroBids вимкнено адміністратором'}
}
async function toggleManualBidsUpdate(){
  const button=$('#bidsManualUpdateToggle'),enabled=button.dataset.enabled==='true';
  if(enabled&&!confirm('Увімкнути ручне оновлення даних Bids? Саме оновлення не буде запущено.'))return;
  button.disabled=true;
  try{const result=await request(`${API}/admin/runtime-features/manual-bids-update`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});renderManualBidsUpdateState(result.feature);toast(`Ручне оновлення Bids ${enabled?'увімкнено':'вимкнено'}`,'success');await loadRuntimeFeatures()}catch(error){button.disabled=false;toast(error.message,'error')}
}
async function toggleSchedulerJob(button){
  const job=button.dataset.schedulerJob,enabled=button.dataset.enabled==='true';
  if(enabled&&!confirm(schedulerEnableConfirmations[job]||`Увімкнути ${schedulerJobLabels[job]||job}?`))return;
  button.disabled=true;
  try{
    await request(`${API}/admin/scheduler-jobs/${encodeURIComponent(job)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});
    toast(`${schedulerJobLabels[job]||job}: ${enabled?'автоматичне оновлення увімкнено':'автоматичне оновлення вимкнено'}`,'success');
    await loadRuntimeFeatures();
  }catch(error){button.disabled=false;toast(error.message,'error')}
}
async function loadRuntimeFeatures(){
  try{
    const features=await request(`${API}/runtime-features`);
    const banner=$('#environmentBanner');
    if(banner){
      const environment=String(features.environment||'local').toLowerCase();
      banner.textContent=environment==='local'?'PQM (LOCAL)':(['test','test_web','web'].includes(environment)?'PQM (WEB TEST)':'PQM (PROD)');
      banner.title='Profzakupivli Qualification Manager';
    }
    const schedulerRoot=$('#schedulerJobs');
    if(schedulerRoot){
      const canManage=role()==='admin';
      schedulerRoot.innerHTML=(features.scheduler_jobs||[]).map(job=>`<article class="scheduler-job ${job.enabled?'enabled':'disabled'}"><header><strong>${esc(schedulerJobLabels[job.job]||job.job)}</strong><span>${job.enabled?'Увімкнено':'Вимкнено'}</span></header><dl><div><dt>Розклад</dt><dd>${esc(job.schedule)}</dd></div><div><dt>Timezone</dt><dd>${esc(job.timezone)}</dd></div><div><dt>Останній запуск</dt><dd>${esc(job.last_finished_at?displayDate(job.last_finished_at):'—')}</dd></div><div><dt>Наступний запуск</dt><dd>${esc(job.enabled&&job.next_run?displayDate(job.next_run):'—')}</dd></div><div><dt>Джерело налаштування</dt><dd>${job.configuration_source==='runtime'?'Адміністратор':'Середовище'}</dd></div></dl>${canManage?`<footer><button type="button" class="ghost scheduler-toggle" data-scheduler-job="${esc(job.job)}" data-enabled="${job.enabled?'false':'true'}">${job.enabled?'Вимкнути':'Увімкнути'}</button></footer>`:''}</article>`).join('');
      schedulerRoot.onclick=event=>{const button=event.target.closest('.scheduler-toggle');if(button)toggleSchedulerJob(button)};
    }
    renderGoogleRuntimeState(features.google_integration||{enabled:Boolean(features.google),configuration_source:'environment'});
    renderManualBidsUpdateState(features.manual_bids_update||{enabled:Boolean(features.bids_update),configuration_source:'environment',mode_supported:features.bids_mode!=='disabled'});
    const disable=(selector,message)=>{const element=$(selector);if(!element)return;element.dataset.runtimeDisabled='1';element.disabled=true;element.title=message};
    if(features.bids_mode==='disabled'){
      disable('#bidsStatusRefresh','Локальна база ProzorroBids не підключена');
      $('#bidsSyncHeadline').textContent='ProzorroBids не підключено до TEST WEB';
    }
    if(!features.powerbi){
      disable('#powerbiExportBtn','Power BI доступний лише в локальному середовищі');
      $('#powerbiStatusMessage').textContent='Power BI вимкнено у TEST WEB';
    }
    if(!features.google){
      disable('#supplierEdrSync','Google integration вимкнено');
      disable('#supplierNazkReviewSync','Google integration вимкнено');
    }
    return features;
  }catch(error){return null}
}
