// One predictable popover model for registry filters/settings. Native details
// keeps keyboard behaviour; this coordinator guarantees a single open panel.
const managedPopoverSelector='.registry-toolbar details,.multi-filter,.toolbar-settings,.advanced-filters';
document.addEventListener('toggle',event=>{
  const opened=event.target;
  if(!(opened instanceof HTMLDetailsElement)||!opened.open||!opened.matches(managedPopoverSelector))return;
  $$(managedPopoverSelector).forEach(item=>{
    if(item!==opened&&item instanceof HTMLDetailsElement&&!item.contains(opened))item.open=false;
  });
},true);
document.addEventListener('pointerdown',event=>{
  $$(managedPopoverSelector).forEach(item=>{
    if(item instanceof HTMLDetailsElement&&item.open&&!item.contains(event.target))item.open=false;
  });
});
